css:
 .widget-container {
  font-size: 16px;
  width: min(100%, 750px);
  margin-inline: auto;
  box-sizing: border-box;
}

 .widget-container * {
  box-sizing: border-box;
}

 .video-hero .img.mt {
  margin-top: 0.5em;
}

 .video-hero img,
 .video-hero video {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
  border: 0;
  margin: 0 !important;
}

 .video-hero-movie {
  position: relative;
}

 .video-hero-movie .badge-left,
 .video-hero-movie .badge-right {
  position: absolute;
  top: 0;
  z-index: 2;
}

 .video-hero-movie .badge-left {
  margin-top: 4%;
  left: 3%;
  width: 38%;
}

 .video-hero-movie .badge-right {
  margin-top: 2%;
  right: 3%;
  width: 27%;
}

 .video-hero-bottom {
  position: relative;
  z-index: 3;
  margin-top: -10%;
}

.survey {
  width: 100%;
  max-width: 800px;
  height: auto;
  margin: 0 auto;
  font-size: min(16px, 3vw);
  display: flex;
  flex-direction: column;
}

.pagination {
  width: 80%;
  height: auto;
  margin: 0 auto;
  display: flex;
  align-items: center;
  position: relative;
  z-index: 0;
}

.pagination .pagination__item {
  font-size: 0.9em;
  color: #fff;
  text-align: center;
  position: relative;
  display: inline-block;
  flex: 1;
}

.pagination .pagination__item:before {
  content: '';
  width: 100%;
  height: auto;
  border-top: 2px solid #ccc;
  position: absolute;
  top: 50%;
  right: 50%;
  left: -50%;
  z-index: -2;
}

.pagination .pagination__item:first-child:before {
  display: none;
}

.pagination .pagination__item.is-active:before {
  border-top-color: #2BAA73;
}

.pagination .pagination__item:after {
  content: '';
  width: 1.4em;
  height: 1.4em;
  border-radius: 0.7em;
  background-color: #ccc;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: block;
  z-index: -1;
}

.pagination .pagination__item.is-active:after {
  background-color: #2BAA73;
}

.survey .question {
  margin-top: 1em;
}

.question {
  width: 100%;
  height: auto;
  display: none;
}

.question.is-active {
  display: block;
}

.question__text {
  font-size: 1.2em;
  font-weight: 700;
  text-align: center;
}

.question__buttons {
  width: 100%;
  height: auto;
  max-width: 350px;
  display: flex;
  justify-content: center;
  align-self: center;
  flex-direction: column;
  margin: 1em auto 0;
}

.question__buttons .button {
  height: auto;
  cursor: pointer;
  font-size: 1.1em;
  font-weight: 700;
  text-align: center;
  border-radius: 5px;
  margin-left: auto;
  margin-right: auto;
}

.question__buttons .button+.button {
  margin-top: 0.5em;
}

.question__buttons .button:hover {
  opacity: 0.7;
}

.question__buttons .button.select__button {
  width: 100%;
  border: none;
  background-color: #FC981C;
  color: #fff;
  padding: 0.8em 0.4em;
}

.question__buttons .button.back__button {
  width: 50%;
  border: 2px solid #008000;
  background-color: #fff;
  color: #008000;
  padding: 0.5em;
  margin-top: 2em;
}

.question .question__iframe {
  width: 100%;
  height: auto;
  max-width: 600px;
  min-height: 100vh;
  margin: 0 auto;
  display: block;
}

@media screen and (max-width: 768px) {
  .question .question__iframe {
    min-height: 100vh;
  }
}

 .bg-wrap {
  background: #ebfcf1;
  padding: 14% 4% 16%;
  box-sizing: border-box;
}

 h2 {
  font-size: min(5.7vw, 36px);
  font-weight: 700;
  line-height: 1;
  margin: 0;
  text-align: center;
}

 .flow-list {
  width: 100%;
  max-width: 1000px;
  margin-top: min(8.3vw, 55px);
  margin-left: auto;
  margin-right: auto;
  padding: 0;
  list-style: none;
}

 .flow-list li {
  position: relative;
  background: #fff;
  border: 1px solid #53b76e;
  margin-bottom: 25px;
  display: grid;
  grid-template-areas: "num head" "body body";
  grid-template-columns: -webkit-min-content auto;
  grid-template-columns: min-content auto;
}

 .flow-list li::after {
  border-color: #f5c021 transparent transparent;
  border-style: solid;
  border-width: 20px 23px 0;
  top: calc(100% + 1px);
  content: "";
  display: block;
  height: 0;
  left: 50%;
  position: absolute;
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
  width: 0;
}

 .flow-list li:last-child {
  margin-bottom: 0;
}

 .flow-list li:last-child::after {
  content: none;
}

 .flow-list .flow-num {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: -webkit-fit-content;
  width: -moz-fit-content;
  width: fit-content;
  height: 100%;
  padding: 0.4em;
  aspect-ratio: 1/1;
  color: #53b76e;
  font-size: clamp(30px, 6.25vw, 50px);
  font-weight: bold;
  line-height: 1;
  border-right: 1px solid #53b76e;
  border-bottom: 1px solid #53b76e;
  grid-area: num;
  box-sizing: border-box;
}

 .flow-list .flow-num::before {
  content: "STEP";
  font-size: 0.4em;
}

 .flow-list .flow-head {
  grid-area: head;
  align-self: center;
  width: -webkit-fit-content;
  width: -moz-fit-content;
  width: fit-content;
  padding: 2% 5%;
  overflow: hidden;
}

 .flow-list .flow-head h3 {
  font-size: clamp(20px, 3.25vw, 26px);
  margin: 0;
}

 .flow-list .flow-body {
  grid-area: body;
  width: -webkit-fit-content;
  width: -moz-fit-content;
  width: fit-content;
  padding: 3% 5%;
  overflow: hidden;
}

 .flow-list .flow-body p {
  color: #1c1c1c;
  font-size: 15px;
  letter-spacing: 0.05em;
  line-height: 2;
  margin: 0 0 0.5em;
}

@media screen and (min-width: 768px) {
   .flow-list li {
    border: 2px solid #53b76e;
    grid-template-areas: "num head" "num body";
  }

   .flow-list li::after {
    top: calc(100% + 2px);
  }

   .flow-list .flow-num {
    height: 100%;
    border-width: 2px;
    border-bottom: none;
    padding: 0 0.6em;
    aspect-ratio: auto;
    box-sizing: border-box;
  }

   .flow-list .flow-body {
    padding-top: 0;
  }
}

 .widget-container {
  font-size: 16px;
  width: 100%;
  margin-inline: auto;
  box-sizing: border-box;
}

 .widget-container * {
  box-sizing: border-box;
}

 .site-footer {
  background: #34404e;
  color: #fff;
  line-height: 1.5;
  padding: 20px 15px 27px;
}

 .site-footer-inner {
  width: 100%;
  max-width: 1000px;
  margin: 0 auto;
}

 .site-footer-logo {
  width: 50%;
  max-width: 235px;
  margin-inline: auto;
  line-height: 1;
}

 .site-footer-logo a {
  display: block;
}

 .site-footer-logo img {
  display: block;
  width: 100%;
  height: auto;
}

 .site-footer-body {
  margin-top: 2em;
}

 .site-footer-areas .head {
  font-size: 0.9em;
  line-height: 1.5;
  margin: 0 0 10px;
  padding: 0;
}

 .site-footer-areas .area {
  margin: 0 0 0.75em;
}

 .site-footer-areas .area:last-child {
  margin-bottom: 0;
}

 .site-footer-areas .label {
  color: #bebebe;
  font-size: 0.8em;
  font-weight: 400;
  line-height: 1.5;
  margin: 0 0 2px;
  padding: 0;
}

 .site-footer-areas .list {
  display: flex;
  flex-wrap: wrap;
  list-style: none;
  margin: 0;
  padding: 0;
}

 .site-footer-areas .list li {
  font-size: 0.8em;
  letter-spacing: 0.8px;
  line-height: 1.5;
  list-style: none;
}

 .site-footer-areas .list li:not(:last-child) {
  margin-right: 5px;
}

 .site-footer-areas .list li:not(:last-child)::after {
  content: '|';
  margin-left: 5px;
}

 .site-footer-links .list {
  display: flex;
  flex-direction: column;
  list-style: none;
  margin: 38px 0 0;
  padding: 0;
}

 .site-footer-links .list li {
  font-size: 0.8em;
  letter-spacing: 0.4px;
  line-height: 1.7;
  list-style: none;
}

 .site-footer-links .list li+li {
  margin-top: 0.75em;
}

 .site-footer-copy {
  font-size: 0.7em;
  line-height: 1.5;
  text-align: center;
  margin: 22px auto 0;
}

 .site-footer a {
  color: #fff;
  text-decoration: underline;
}

 .site-footer a:hover {
  opacity: 0.7;
}

@media (min-width: 768px) {
   .site-footer {
    padding: 40px 15px 30px;
  }

   .site-footer-logo {
    width: 305px;
    max-width: none;
    margin-inline: unset;
  }

   .site-footer-body {
    display: flex;
    margin-top: 1.5em;
  }

   .site-footer-areas {
    margin-right: 2.5em;
  }

   .site-footer-areas .head {
    margin: 0 0 18px;
  }

   .site-footer-areas .area {
    display: flex;
  }

   .site-footer-areas .label {
    min-width: 90px;
    margin: 0 16px 0 0;
  }

   .site-footer-links .list {
    margin: 0;
  }

   .site-footer-links .list li {
    letter-spacing: 0.8px;
    line-height: 1.5;
  }

   .site-footer-links .list li+li {
    margin-top: 11px;
  }

   .site-footer-copy {
    font-size: 0.9em;
    letter-spacing: 0.5px;
    margin: 31px auto 0;
  }
}

.multiple-carousel02 {
  width: calc(90% - 60px);
  height: auto;
  position: relative;
  padding: 0 30px;
  margin: 0 auto;
  font-size: min(16px, 3vw);
}

.multiple-carousel02 .swiper-button-prev::after {
  content: '';
  width: 20px;
  height: 20px !important;
  border-width: 0 0 6px 6px;
  border-color: #4acb93;
  border-style: solid;
  transform-origin: center;
  transform: rotate(45deg);
}

.multiple-carousel02 .swiper-button-next::after {
  content: '';
  width: 20px;
  height: 20px !important;
  border-width: 0 6px 6px 0;
  border-color: #4acb93;
  border-style: solid;
  transform-origin: center;
  transform: rotate(-45deg);
}

.multiple-carousel02 .swiper {
  width: 100%;
  height: auto;
  padding: 0 10px 1em;
  margin-left: auto;
  margin-right: auto;
  position: relative;
  z-index: 1;
  touch-action: pan-y;
  box-sizing: border-box;
}

.multiple-carousel02 .swiper .swiper-slide {
  width: 100%;
  height: auto;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);
  display: flex;
  flex-direction: column;
}

.multiple-carousel02 .swiper .swiper-slide .wrap-img {
  margin: 0;
  padding: 0;
}

.multiple-carousel02 .swiper .swiper-slide .wrap-img>img {
  max-width: 100%;
  width: 100%;
  height: auto;
}

.multiple-carousel02 .swiper .swiper-slide .wrap-txt {
  padding: 10px 16px;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
}

.multiple-carousel02 .swiper .swiper-slide .wrap-txt>p {
  font-size: 1em;
  margin: 1em 0;
  line-height: 1.5;
}

.multiple-carousel02 .swiper .swiper-slide .wrap-txt>p:first-of-type {
  margin-top: 0;
}

.detail-link {
  display: inline-flex;
  align-items: center;
  gap: 0.5em;
  font-size: 1em;
  text-decoration: none;
}

.detail-link:after {
  content: '';
  width: 10px;
  height: 10px;
  border-width: 2px 2px 0 0;
  border-color: #4acb93;
  border-style: solid;
  transform: rotate(45deg);
  flex-shrink: 0;
}

.multiple-carousel02 .swiper .swiper-slide .wrap-txt .detail-link {
  align-self: center;
  margin-top: auto;
  font-weight: 700;
  color: #4acb93;
}

.item__link {
  text-align: right;
}

.item__link .detail-link {
  color: #000;
  margin-top: 1em;
}

@media screen and (max-width: 768px) {
  .multiple-carousel02 {
    width: 100%;
    padding: 0;
  }

  .swiper-button-next,
  .swiper-button-prev {
    display: none !important;
  }

  .detail-link:after {
    content: '';
    width: 5px;
    height: 5px;
    border-width: 2px 2px 0 0;
    border-color: #4acb93;
    border-style: solid;
    transform: rotate(45deg);
    flex-shrink: 0;
  }

  .item__link {
    text-align: center;
  }
}

 .widget-container {
  font-size: 16px;
  width: 100%;
  margin-inline: auto;
  box-sizing: border-box;
}

 .widget-container * {
  box-sizing: border-box;
}

 .cv-photo-overlay {
  position: relative;
  color: #fff;
  line-height: 1.5;
  min-height: 23em;
  overflow: hidden;
}

 .cv-photo-overlay .br-pc {
  display: none;
}

 .cv-photo-overlay-bg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

 .cv-photo-overlay-bg img {
  display: block;
  width: 100%;
  height: 100% !important;
  object-fit: cover;
}

 .cv-photo-overlay-bg .img-pc {
  display: none !important;
}

 .cv-photo-overlay-bg::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: #4bcb92;
  opacity: 0;
}

 .cv-photo-overlay-inner {
  position: relative;
  z-index: 2;
  max-width: 880px;
  margin: 0 auto;
  padding: 4.9em 1em 2.6em;
  text-align: center;
}

 .cv-photo-overlay-catch .inner {
  display: inline-block;
  font-size: 1.05em;
  font-weight: 600;
  line-height: 1.4;
}

 .cv-photo-overlay-catch .em {
  font-size: 130%;
}

 .cv-photo-overlay .cv-photo-overlay-cta {
  display: flex;
  align-items: center;
  gap: 0.7em;
  max-width: 620px;
  margin: 1.5em auto 0;
  background: #fc981c;
  color: #fff;
  text-decoration: none;
  border-radius: 0.55em;
  padding: 1em 0.8em;
  box-shadow: 0 0.25em 0.3em rgba(86, 86, 86, 0.25);
}

 .cv-photo-overlay .cv-photo-overlay-cta:hover {
  opacity: 0.85;
}

 .cv-photo-overlay .cv-photo-overlay-cta .tag {
  flex-shrink: 0;
  background: #fff;
  color: #fc981c;
  font-size: 0.8em;
  font-weight: 600;
  line-height: 1.3;
  text-align: center;
  border-radius: 0.25em;
  padding: 0.4em 0.5em;
}

 .cv-photo-overlay .cv-photo-overlay-cta .text {
  flex: 1;
  min-width: 0;
  display: block;
  text-align: center;
  line-height: 1.3;
}

 .cv-photo-overlay .cv-photo-overlay-cta .text .sub {
  display: block;
  font-size: 0.72em;
  font-weight: 600;
}

 .cv-photo-overlay .cv-photo-overlay-cta .text .main {
  display: block;
  font-size: 3.7vw;
  font-weight: 600;
}

 .cv-photo-overlay .cv-photo-overlay-cta .arrow {
  flex-shrink: 0;
  position: relative;
  width: 1.7em;
  height: 1.7em;
  border: 0.14em solid #fff;
  border-radius: 50%;
}

 .cv-photo-overlay .cv-photo-overlay-cta .arrow::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0.5em;
  height: 0.5em;
  border-right: 0.14em solid #fff;
  border-bottom: 0.14em solid #fff;
  transform: translate(-50%, -70%) rotate(45deg);
}

 .cv-photo-overlay-note {
  max-width: 620px;
  margin: 1.2em auto 0;
  font-size: 0.64em;
  line-height: 1.6;
  text-align: left;
}

@media (min-width: 768px) {
   .cv-photo-overlay .br-sp {
    display: none;
  }

   .cv-photo-overlay .br-pc {
    display: inline;
  }

   .cv-photo-overlay-bg .img-pc {
    display: block !important;
  }

   .cv-photo-overlay-bg .img-sp {
    display: none !important;
  }

   .cv-photo-overlay-inner {
    padding: 4.9em 1em 2.6em;
  }

   .cv-photo-overlay-catch .inner {
    font-size: 1.4em;
  }

   .cv-photo-overlay .cv-photo-overlay-cta {
    gap: 0.8em;
    padding: 1.15em 1em;
    margin-top: 1.6em;
  }

   .cv-photo-overlay .cv-photo-overlay-cta .tag {
    font-size: 0.82em;
    padding: 0.45em 0.75em;
  }

   .cv-photo-overlay .cv-photo-overlay-cta .tag br {
    display: none;
  }

   .cv-photo-overlay .cv-photo-overlay-cta .text .sub {
    font-size: 0.9em;
  }

   .cv-photo-overlay .cv-photo-overlay-cta .text .main {
    font-size: 1.25em;
  }

   .cv-photo-overlay .cv-photo-overlay-cta .arrow {
    width: 1.75em;
    height: 1.75em;
  }

   .cv-photo-overlay-note {
    font-size: 0.66em;
    margin-top: 1.3em;
    padding-left: 0.2em;
  }
}

@media (max-width: 360px) {
   .cv-photo-overlay .cv-photo-overlay-cta {
    gap: 0.5em;
    padding: 0.8em 0.6em;
  }

   .cv-photo-overlay .cv-photo-overlay-cta .tag {
    font-size: 0.74em;
  }

   .cv-photo-overlay .cv-photo-overlay-cta .text .main {
    font-size: 3.5vw;
  }
}

 h2 {
  font-size: min(4.75vw, 38px);
  font-weight: 700;
  line-height: 1.38;
  margin: 0;
  text-align: center;
}

 .point-trouble {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  margin: 4.8% auto 0;
  width: 85vw;
  max-width: 800px;
  text-align: center;
  list-style: none;
  padding: 0;
}

 .point-trouble li {
  align-items: center;
  border-radius: 100vh;
  color: #fff;
  display: flex;
  font-size: min(4vw, 32px);
  font-weight: 700;
  height: auto;
  justify-content: center;
  line-height: 1.33;
  position: relative;
  width: 45%;
  aspect-ratio: 1/1;
}

 .point-trouble li:first-child,
 .point-trouble li:nth-child(4) {
  background: #4bcb92;
}

 .point-trouble li:nth-child(2),
 .point-trouble li:nth-child(3) {
  background: #fb9a1d;
}

 .point-trouble li:nth-child(n+3) {
  margin: 7.5% 0 0;
}

 .point-trouble li::after {
  border-style: solid;
  border-width: min(8vw, 64px) min(6.5vw, 52px) 0;
  content: "";
  display: block;
  height: 0;
  left: 50%;
  position: absolute;
  bottom: -10%;
  transform: translateX(-50%);
  width: 0;
}

 .point-trouble li:first-child::after,
 .point-trouble li:nth-child(4)::after {
  border-color: #4bcb92 transparent transparent;
}

 .point-trouble li:nth-child(2):after,
 .point-trouble li:nth-child(3):after {
  border-color: #fb9a1d transparent transparent;
}


@media screen and (min-width: 768px) {
   h2 {
    font-size: 28px;
  }

   .point-trouble {
    margin: 18px auto 0;
    width: 100%;
    min-width: 1000px;
  }

   .point-trouble li {
    font-size: 20px;
    height: 210px;
    line-height: 1.4;
    width: 210px;
  }

   .point-trouble li:nth-child(odd) {
    background: #4bcb92;
  }

   .point-trouble li:nth-child(2n) {
    background: #fb9a1d;
  }

   .point-trouble li:nth-child(n+3) {
    margin: 0;
  }

   .point-trouble li::after {
    border-width: 42px 34.5px 0;
    top: 187px;
  }

   .point-trouble li:nth-child(odd):after {
    border-color: #4bcb92 transparent transparent;
  }

   .point-trouble li:nth-child(2n):after {
    border-color: #fb9a1d transparent transparent;
  }
}

.flow {
  width: 96%;
  height: auto;
  margin: 0 2%;
  padding: 1em 2%;
  font-size: min(16px, 3vw);
  background-color: #4acb93;
  box-sizing: border-box;
}

.flow p {
  margin: 0;
}

.flow__title {
  color: #fff;
  text-align: center;
  font-size: 1.5em;
  font-weight: 700;
}

.flow__list {
  width: 100%;
  height: auto;
  margin-top: 1em;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: flex-start;
}

.flow__item {
  width: calc(31% - 2em);
  height: auto;
  padding: 1em;
  background-color: #efefef;
  position: relative;
}

.flow__item:after {
  content: '';
  display: inline-block;
  width: 10px;
